const track0 = {
  color: '#9be7ff',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["Ld = \\Rev\\,\\Dly\\,\\Cho\\Big[\\tfrac{1}{d}\\tanh\\!\\Big(d\\,\\LP^{Q=1.4}_{f_c}\\LP_{f_c}\\big(\\tfrac12\\saw g + \\tfrac12\\saw 1.0052g + 0.3\\sq\\tfrac g2\\big)\\Big)\\Big]","f_c = 1100 + 2600v\\,e^{-t/0.3},\\quad g = f\\cdot 2^{\\,0.15\\min(1, t/0.5)\\sin(2\\pi\\cdot 5.3T)/12}\\ \\text{(портаменто 30 мс)}"],
  audio({ bpm }) {
    const sec = 60 / bpm, s = monoSynth({ cutoff: 1100, env: 2600, res: 1.4, decay: 0.3, glide: 30, sub: 0.3 }), ch = chorus({ mix: 0.35, rate: 0.6 })
    const echo = delay({ time: sec * 0.75, feedback: 0.35, wet: 0.24 }), verb = reverb({ room: 0.86, damp: 0.35, wet: 0.3 })
    let n = 0
    return x => {
      const m = leadAt(x), t = x * sec
      if (m) n = m.n
      const vib = m ? 0.15 * Math.min(1, (m.τ * sec) / 0.5) * sin(TAU * 5.3 * t) : 0
      const y = 0.72 * s(hz(n + vib, C4), !!m && m.u < 0.92, 0.85)
      return verb(...echo(...ch(...pan(y, 0.12))))
    }
  },
}

