    const snare = snareDrum({ tone: 220, cutoff: 1800, decay: 18 }), tick = hatDrum({ cutoff: 10000, decay: 120 }), tom = taikoDrum({ pitch: 90, decay: 0.7, crack: 0.35, boom: 0.3, seed: 12 })
